TLM.f("Sancti/06-02",{"officium":"Ss. Marcellini, Petri, atque Erasmi Martyrum","rule":["Evangelium non appropriatum","vide C3;"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 33:18"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"ref","la":"Ps 33:2 Benedícam Dóminum"},{"k":"text","la":"in omni témpore: semper laus ejus in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."}],"Oratio":[{"k":"text","la":"Deus, qui nos ánnua beatórum Mártyrum tuórum Marcellíni, Petri atque Erásmi sollemnitáte lætíficas: præsta, quǽsumus; ut, quorum gaudémus méritis, accendámur exémplis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 8:18-23"},{"k":"text","la":"Fratres: Exístimo, quod non sunt condígnæ passiónes hujus témporis ad futúram glóriam, quæ revelábitur in nobis. Nam exspectátio creatúræ revelatiónem filiórum Dei exspéctat. Vanitáti enim creatúra subjécta est, non volens, sed propter eum, qui subjécit eam in spe: quia et ipsa creatúra liberábitur a servitúte corruptiónis, in libertátem glóriæ filiórum Dei. Scimus enim, quod omnis creatúra ingemíscit et párturit usque adhuc. Non solum autem illa, sed et nos ipsi primítias spíritus habéntes: et ipsi intra nos gémimus, adoptiónem filiórum Dei exspectántes, redemptiónem córporis nostri: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvabit. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Joann 15-16"},{"k":"text","la":"Ego vos elégi de mundo, ut eátis, et fructum afferátis; et fructus vester máneat. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, alleluja."},{"k":"ref","la":"Ps 15:16"},{"k":"text","la":"Ego vos elégi de mundo, ut eátis, et fructum afferátis; et fructus vester máneat. Allelúja."},{"k":"ref","la":"Ps 115:15"},{"k":"text","la":"Pretiósa in conspéctu Dómini mors Sanctórum ejus. Allelúja."}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 21:9-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum audiéritis prǽlia et seditiónes, nolíte terréri: opórtet primum hæc fíeri, sed nondum statim finis. Tunc dicébat illis: Surget gens contra gentem, et regnum advérsus regnum. Et terræmótus magni erunt per loca, et pestiléntiæ, et fames, terrorésque de coelo, et signa magna erunt. Sed ante hæc ómnia injícient vobis manus suas, et persequéntur tradéntes in synagógas et custódias, trahéntes ad reges et praesides propter nomen meum: contínget autem vobis in testimónium. Pónite ergo in córdibus vestris non præmeditári, quemádmodum respondeátis. Ego enim dabo vobis os et sapiéntiam, cui non potérunt resístere et contradícere omnes adversárii vestri. Tradémini autem a paréntibus, et frátribus, et cognátis, et amícis, et morte affícient ex vobis: et éritis ódio ómnibus propter nomen meum: et capíllus de cápite vestro non períbit. In patiéntia vestra possidébitis ánimas vestras."}],"Offertorium":[{"k":"ref","la":"Ps 31:11"},{"k":"text","la":"Lætámini in Dómino et exsultáte, justi: et gloriámini, omnes recti corde, allelúja, allelúja."}],"Secreta":[{"k":"text","la":"Hæc hóstia, quǽsumus, Dómine, quam sanctórum Martyrum tuórum natalítia recenséntes offérimus: et víncula nostræ pravitátis absólvat, et tuæ nobis misericórdiæ dona concíliet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 3:1; 3:2; 3:3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiæ visi sunt óculis insipiéntium mori: illi autem sunt in pace."}],"Postcommunio":[{"k":"text","la":"Sacro múnere satiáti, súpplices te, Dómine, deprecámur: ut, quod débitæ servitútis celebrámus offício, salvatiónis tuæ sentiámus augméntum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"0eca7456f5b70867":{"t":"<i>Pomolimo se</i>.\nBože, koji nas razveseljuješ godišnjom svetkovinom blaženih mučenika svojih Marcelina, Petra i Erazma podaj, molimo, da se raspalimo primjerima onih kojih se zaslugama radujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji nas razveseljuješ godišnjom svetkovinom bi. mučenika svojih Marcelina, Petra i Erasma, podaj, molimo, da nas raspale primjeri onih, kojih zasluge uživamo, po G. n.","knRef":"Kniewald 1942, str. 584–585 (snimka 293) (OCR)"},"a555b3c4944c6e7d":{"t":"Ovaj dar, molimo, Gospodine, koji prikazujemo, slaveći nebeski rođendan svetih tvojih mučenika, neka nas odriješi od veza naše zloće i neka nam isprosi darove tvoga milosrđa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ova žrtva, molimo. Gospodine, što je prinosimo slaveći rođeni dan Tvojih mučenika, odriješila i okove naše zloće i isprosila nam darove Tvoga milosrđa, po G. n.","knRef":"Kniewald 1942, str. 584–585 (snimka 293) (OCR)"},"d6a422c869ef8ba9":{"t":"<i>Pomolimo se</i>.\nNasićeni svetim darom, ponizno te, Gospodine, molimo, da ovo što slavimo službom dužne pokornosti osjetimo kao povećanje tvoga spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Nahranjeni svetim darom ponizno Te molimo, G^podine. da vršeći dužnu službu osjetimo uvećanje Tvoga spasenja, po G. n.","knRef":"Kniewald 1942, str. 586–587 (snimka 294) (OCR)"}}});
